<?php requirePermission('finance');
if($_SERVER['REQUEST_METHOD']==='POST'){checkCsrf();$type=$_POST['type']??'';$id=(int)($_POST['id']??0);if(in_array($type,['pay','receive'],true)&&$id){if($type==='pay'){$pdo->prepare('UPDATE accounts_payable SET status="paid",paid_at=NOW() WHERE id=?')->execute([$id]);flash('success','Conta marcada como paga.');}else{$pdo->prepare('UPDATE accounts_receivable SET status="received",received_at=NOW() WHERE id=?')->execute([$id]);flash('success','Recebimento confirmado.');}}redirect('index.php?page=finance');}
$pay=$pdo->query('SELECT a.*,s.name supplier FROM accounts_payable a LEFT JOIN suppliers s ON s.id=a.supplier_id ORDER BY (a.status="open") DESC,a.due_date')->fetchAll();$rec=$pdo->query('SELECT a.*,c.name customer FROM accounts_receivable a LEFT JOIN customers c ON c.id=a.customer_id ORDER BY (a.status="open") DESC,a.due_date')->fetchAll();$openPay=0;$openRec=0;foreach($pay as $x)if($x['status']==='open')$openPay+=$x['amount'];foreach($rec as $x)if($x['status']==='open')$openRec+=$x['amount'];$title='Financeiro';require __DIR__.'/../../includes/header.php';?>
<div class="page-head"><div><h1>Financeiro</h1><p>Contas a pagar, contas a receber e crediário.</p></div></div><div class="cards"><div class="stat"><small>A pagar em aberto</small><strong><?=money($openPay)?></strong></div><div class="stat"><small>A receber em aberto</small><strong><?=money($openRec)?></strong></div><div class="stat"><small>Saldo projetado</small><strong><?=money($openRec-$openPay)?></strong></div></div><div class="grid two"><section class="panel"><h2>Contas a pagar</h2><table><thead><tr><th>Descrição</th><th>Fornecedor</th><th>Venc.</th><th>Valor</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($pay as $x):?><tr><td><?=e($x['description'])?></td><td><?=e($x['supplier']?:'-')?></td><td><?=date('d/m/Y',strtotime($x['due_date']))?></td><td><?=money($x['amount'])?></td><td><span class="badge <?=$x['status']==='paid'?'ok':'danger'?>"><?=e($x['status'])?></span></td><td><?php if($x['status']==='open'):?><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="type" value="pay"><input type="hidden" name="id" value="<?=$x['id']?>"><button class="link-btn">Baixar</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></section><section class="panel"><h2>Contas a receber</h2><table><thead><tr><th>Descrição</th><th>Cliente</th><th>Venc.</th><th>Valor</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($rec as $x):?><tr><td><?=e($x['description'])?></td><td><?=e($x['customer']?:'-')?></td><td><?=date('d/m/Y',strtotime($x['due_date']))?></td><td><?=money($x['amount'])?></td><td><span class="badge <?=$x['status']==='received'?'ok':'danger'?>"><?=e($x['status'])?></span></td><td><?php if($x['status']==='open'):?><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="type" value="receive"><input type="hidden" name="id" value="<?=$x['id']?>"><button class="link-btn">Receber</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></section></div><?php require __DIR__.'/../../includes/footer.php';?>
